const {test}=require('node:test'); const assert=require('node:assert/strict'); const fs=require('node:fs'); const vm=require('node:vm');
const html=fs.readFileSync('submodules/one-piece/packages/engine/src/automation/search/web/index.src.html','utf8');
const code=html.slice(html.indexOf('let running = null;'),html.indexOf('/* ---------- stats'));
function harness(){const workers=[];class Worker{constructor(){workers.push(this);}postMessage(m){if(m.type==='run')this.job=m;}terminate(){this.terminated=true;}result(r){this.onmessage({data:{type:'result',result:r}});}done(){this.onmessage({data:{type:'done',id:this.job.id}});}}
const ctx={Worker,NIGHTLY:null,document:{addEventListener(){}},window:{addEventListener(){}},setTimeout,JSON};vm.createContext(ctx);vm.runInContext(code+'\ndrawBatchQueue=()=>{};this.tasks=batchTasks;',ctx);return {ctx,workers};}
const tick=()=>new Promise(r=>setTimeout(r,10));
test('serial queue snapshots exact lists and advances once',async()=>{const{ctx,workers}=harness();const jobs=[{a:{name:'Luffy one',leader:'L',main:['x','x']},b:{name:'Luffy two',leader:'L',main:['x','y']}}];const p=ctx.runJobs(jobs,'fast',1,()=>{});const q=ctx.runJobs(jobs,'fast',1,()=>{});jobs[0].a.main[0]='changed';assert.equal(workers.length,1);assert.equal(ctx.tasks[0].jobs[0].a.main[0],'x');workers[0].result({});workers[0].done();await p;await tick();assert.equal(workers.length,2);workers[1].result({});workers[1].done();await q;assert.deepEqual(ctx.tasks.map(t=>t.state).join(','),'Completed,Completed');});
test('cancelling queued job never starts it and leaves active untouched',async()=>{const{ctx,workers}=harness();const p=ctx.runJobs([{}],'fast',1,()=>{});const q=ctx.runJobs([{}],'fast',1,()=>{});ctx.cancelBatch(2);assert.equal((await q).stopped,true);assert.equal(workers[0].terminated,undefined);ctx.cancelBatch(1);await p;await tick();assert.equal(workers.length,1);assert.equal(ctx.tasks[1].state,'Cancelled');});
test('active stop ignores late results and starts next task',async()=>{const{ctx,workers}=harness();let calls=0;const p=ctx.runJobs([{}],'fast',1,()=>calls++);const q=ctx.runJobs([{}],'fast',1,()=>calls++);ctx.cancelBatch(1);workers[0].result({});assert.equal((await p).stopped,true);await tick();assert.equal(calls,0);workers[1].result({});workers[1].done();await q;assert.equal(calls,1);});
test('worker errors terminate all current workers, resolve once, keep next task',async()=>{const{ctx,workers}=harness();const p=ctx.runJobs(Array(6).fill({}),'fast',2,()=>{});const q=ctx.runJobs([{}],'fast',1,()=>{});workers[0].onerror({message:'failure'});const o=await p;assert.equal(o.errors[0],'failure');assert.ok(workers.slice(0,2).every(w=>w.terminated));await tick();workers[2].result({});workers[2].done();await q;assert.equal(ctx.tasks[0].state,'Incomplete');});
test('queue tab is in navigation visibility routing',()=>{assert.match(html,/\["home", "batches", "test"/);});

const pairCode=html.slice(html.indexOf('function buildPairJobs('),html.indexOf('$("batchEnqueue").onclick='));
test('two-by-two groups produce exactly four separate pairs with balanced first seats',()=>{const c={};vm.createContext(c);vm.runInContext(pairCode,c);const d=[{name:'L1',leader:'L',group:'A'},{name:'L2',leader:'L',group:'A'},{name:'R1',leader:'R',group:'B'},{name:'R2',leader:'R',group:'B'}];const jobs=c.buildPairJobs(d,2,true);assert.equal(jobs.length,8);assert.equal(new Set(jobs.map(j=>j.a.name+'|'+j.b.name)).size,4);assert.ok(jobs.every(j=>j.a.group==='A'&&j.b.group==='B'));assert.equal(jobs.filter(j=>j.k%2===0).length,4);assert.equal(c.buildPairJobs(d,2,false).length,12);});
